// Keeps only the last 10 plain messages. Nothing is logged.
const b = $('Webhook').first().json.body || {};
const msgs = (Array.isArray(b.messages) ? b.messages : [])
  .filter((m) => m && (m.role === 'user' || m.role === 'assistant') && typeof m.content === 'string')
  .slice(-10)
  .map((m) => ({ role: m.role, content: m.content.slice(0, 1000) }));
if (!msgs.length) msgs.push({ role: 'user', content: 'Hello' });
const screen = ['today', 'health', 'records', 'family', 'safety'].includes(b.screen) ? b.screen : 'today';
const SYSTEM = "You are Bantay, a calm helper inside a family health and safety app used in the Philippines. Use plain English, short sentences, no jargon. Be kind.\nRules you never break:\n1. Never diagnose. Never say a person has or probably has a condition. Never tell anyone to start, stop or change a medicine or a dose.\n2. Never give a medicine dose beyond what the family already logged or what is printed on their own prescription. If asked, say to check with the doctor or pharmacist.\n3. If something sounds urgent (chest pain, trouble breathing, stroke signs, very high or low sugar with symptoms, fainting, bleeding, a child or older person who is very unwell, thoughts of self harm), say so plainly: call 911 now, or go to the nearest hospital, and tell the doctor. Do not try to manage it yourself.\n4. For non-urgent health worries, point to the family doctor. Reading ranges in the app are a general guide, not the doctor's target.\n5. Never claim Bantay warns of earthquakes or local tsunamis. For hazards, point to PHIVOLCS, PAGASA and the local DRRMO.\n6. To save anything (a reading, a medicine taken, an activity) you must call the matching tool. That only makes a draft. The person confirms it. Never say it is saved.\n7. Use explain_term for questions about a medical word. Keep the answer to three short sentences and general, not about one person.\n8. Use open_screen when the person wants to see a screen. Use whats_the_weather for weather questions.\n9. Do not use emdashes. Do not repeat health numbers back unless needed.\nThe current screen name is given in the first user context line.";
const TOOLS = [{"type":"function","function":{"name":"log_reading","description":"Draft a health reading (for example blood sugar, blood pressure, HbA1c) for the user to confirm.","parameters":{"type":"object","properties":{"person":{"type":"string","description":"Name of the family member, as the user said it"},"test":{"type":"string","description":"Test name, for example HbA1c or fasting glucose"},"value":{"type":"number"},"unit":{"type":"string","description":"Unit, for example mg/dL"},"takenAt":{"type":"string","description":"ISO date or time, empty means now"}},"required":["person","test","value"]}}},{"type":"function","function":{"name":"log_med_taken","description":"Draft a note that a medicine was taken, for the user to confirm.","parameters":{"type":"object","properties":{"person":{"type":"string","description":"Name of the family member, as the user said it"},"name":{"type":"string","description":"Medicine name as the user said it"},"takenAt":{"type":"string","description":"ISO time, empty means now"}},"required":["person","name"]}}},{"type":"function","function":{"name":"log_activity","description":"Draft an activity (walk, exercise) for the user to confirm.","parameters":{"type":"object","properties":{"person":{"type":"string","description":"Name of the family member, as the user said it"},"kind":{"type":"string","description":"walk, exercise, and so on"},"minutes":{"type":"number"},"steps":{"type":"number"},"startedAt":{"type":"string","description":"ISO time, empty means now"}},"required":["person","kind"]}}},{"type":"function","function":{"name":"open_screen","description":"Offer to open one screen of the app.","parameters":{"type":"object","properties":{"tab":{"type":"string","enum":["today","health","records","family","safety"]}},"required":["tab"]}}},{"type":"function","function":{"name":"explain_term","description":"Explain a medical or safety word in plain English, with the best public source.","parameters":{"type":"object","properties":{"term":{"type":"string"},"answer":{"type":"string","description":"At most three short sentences"},"source":{"type":"string","enum":["medlineplus","wikipedia","kiwix"]}},"required":["term","answer","source"]}}},{"type":"function","function":{"name":"whats_the_weather","description":"Show the current weather for where the user is.","parameters":{"type":"object","properties":{}}}}];
return [{ json: { payload: {
  models: ["google/gemini-3.5-flash-lite", "anthropic/claude-haiku-5.5"],
  messages: [{ role: 'system', content: SYSTEM + '\nCurrent screen: ' + screen }, ...msgs],
  tools: TOOLS,
  tool_choice: 'auto',
  provider: { zdr: true, data_collection: 'deny', require_parameters: true },
  max_tokens: 600
} } }];

const r = $input.first().json;
const m = r && r.choices && r.choices[0] && r.choices[0].message;
const OK = ['log_reading', 'log_med_taken', 'log_activity', 'open_screen', 'explain_term', 'whats_the_weather'];
if (!m) return [{ json: { reply: 'I could not answer just now. Please try again. For anything urgent, call your doctor or 911.', tool_calls: [] } }];
const tool_calls = [];
for (const c of m.tool_calls || []) {
  try { if (c.function && OK.includes(c.function.name)) tool_calls.push({ name: c.function.name, arguments: JSON.parse(c.function.arguments || '{}') }); } catch (e) { /* skip bad arguments */ }
}
return [{ json: { reply: String(m.content || '').slice(0, 2000), tool_calls } }];
